"""Arrow schema of a v1 trace (column order and units per docs/11 §6.2)."""


def write_trace(trace: Trace, path: Path) -> None:
    """Write ``trace`` to ``path`` as zstd-compressed Parquet (parent directories must exist).

    Raises:
        roboprobe.core.errors.ValidationError: If ``trace.meta`` is not JSON-serialisable
            (for example it holds NaN).
    """
    try:
        file_metadata = _file_metadata(trace)
    except (TypeError, ValueError) as exc:
        raise _invalid(path, [f"meta is not JSON-serialisable: {exc}"]) from exc
    arrays: dict[str, Any] = {name: getattr(trace, name) for name, _, _ in _COLUMNS[:-1]}
    arrays["rtf"] = trace.rtf if trace.rtf is not None else pa.nulls(trace.n_samples, pa.float32())
    table = pa.table(arrays, schema=TRACE_SCHEMA.with_metadata(file_metadata))
    pq.write_table(table, path, compression=_COMPRESSION)


def read_trace(path: Path) -> Trace:
    """Read a v1 trace written by :func:`write_trace` (or any producer of :data:`TRACE_SCHEMA`).

    Raises:
        roboprobe.core.errors.NotFoundError: If ``path`` does not exist.
        roboprobe.core.errors.ValidationError: If the file is not Parquet, has another schema
            version, misses columns or metadata, has wrong column types, or violates
            :class:`Trace` invariants. ``context["errors"]`` lists the problems.
    """
    if not path.is_file():
        msg = f"trace not found: {path}"
        raise errors.NotFoundError(msg, context={"path": str(path)})
    try:
        table = pq.read_table(path)
    except (pa.ArrowInvalid, OSError) as exc:
        raise _invalid(path, [f"not a readable Parquet file: {exc}"]) from exc
    file_meta = _decode_file_metadata(path, table.schema.metadata or {})
    _check_columns(path, table.schema)
    columns: dict[str, Any] = {}
    for name, _, _ in _COLUMNS[:-1]:
        column = table.column(name)
        if column.null_count:
            raise _invalid(path, [f"column {name} contains nulls"])
        columns[name] = column.to_numpy()
    rtf = table.column("rtf")
    rtf_values = None if rtf.null_count == len(rtf) else rtf.to_numpy(zero_copy_only=False)
    if rtf_values is not None and rtf.null_count:
        raise _invalid(path, ["column rtf is partially null"])
    try:
        return Trace(
            **columns,
            goal_x=file_meta["goal_x"],
            goal_y=file_meta["goal_y"],
            meta=file_meta["meta"],
            rtf=rtf_values,
        )
    except (TypeError, ValueError) as exc:
        raise _invalid(path, [str(exc)]) from exc


def validate_trace(trace: Trace, *, min_hz: float, max_gap_s: float) -> tuple[str, ...]:
    """Check sampling quality against FR-RUN-004 (rate >= ``min_hz``, gaps <= ``max_gap_s``).

    Column presence, dtypes and a strictly increasing ``t`` are already guaranteed by
    :class:`Trace` and :func:`read_trace`. Thresholds come from the caller's settings.

    Returns:
        Human-readable problems; empty if the trace is valid.
    """
    if trace.n_samples < _MIN_SAMPLES_FOR_RATE:
        return (f"trace has {trace.n_samples} sample(s); at least {_MIN_SAMPLES_FOR_RATE} needed",)
    problems: list[str] = []
    rate_hz = (trace.n_samples - 1) / trace.duration_s
    if rate_hz < min_hz:
        problems.append(f"mean sample rate {rate_hz:.3g} Hz is below {min_hz:g} Hz")
    gaps = np.diff(trace.t)
    worst = int(np.argmax(gaps))
    if gaps[worst] > max_gap_s:
        n_gaps = int(np.count_nonzero(gaps > max_gap_s))
        problems.append(
            f"{n_gaps} gap(s) exceed {max_gap_s:g} s; "
            f"largest {gaps[worst]:.3g} s at t={trace.t[worst]:.3f} s"
        )
    return tuple(problems)


def _file_metadata(trace: Trace) -> dict[str, str]:
    meta = dict(trace.meta)
    encoded = {
        "trace_schema_version": json.dumps(TRACE_SCHEMA_VERSION),
        "goal_x": json.dumps(trace.goal_x),
        "goal_y": json.dumps(trace.goal_y),
        "meta": json.dumps(meta, sort_keys=True, allow_nan=False),
    }
    encoded.update({key: json.dumps(meta[key]) for key in _PROMOTED_META_KEYS if key in meta})
    return encoded


def _decode_file_metadata(path: Path, raw: Mapping[bytes, bytes]) -> dict[str, Any]:
    text = {key.decode(): value.decode() for key, value in raw.items()}
    missing = [key for key in _REQUIRED_FILE_KEYS if key not in text]
    if missing:
        raise _invalid(path, [f"missing file metadata: {', '.join(missing)}"])
    try:
        decoded = {key: json.loads(text[key]) for key in _REQUIRED_FILE_KEYS}
    except json.JSONDecodeError as exc:
        raise _invalid(path, [f"file metadata is not JSON: {exc}"]) from exc
    version = decoded["trace_schema_version"]
    if version != TRACE_SCHEMA_VERSION:
        raise _invalid(path, [f"unsupported trace_schema_version {version!r}"])
    problems = [
        f"{key} must be a number"
        for key in ("goal_x", "goal_y")
        if isinstance(decoded[key], bool) or not isinstance(decoded[key], int | float)
    ]
    if not isinstance(decoded["meta"], dict):
        problems.append("meta must be a JSON object")
    if problems:
        raise _invalid(path, problems)
    return decoded


def _check_columns(path: Path, schema: pa.Schema) -> None:
    problems: list[str] = []
    for name, dtype, _ in _COLUMNS:
        index = schema.get_field_index(name)
        if index < 0:
            problems.append(f"missing column {name}")
        elif not schema.field(index).type.equals(dtype):
            problems.append(f"column {name} has type {schema.field(index).type}, expected {dtype}")
    if problems:
        raise _invalid(path, problems)


def _invalid(path: Path, problems: list[str]) -> errors.ValidationError:
    issues: list[Any] = [{"path": "", "message": problem} for problem in problems]
    return errors.ValidationError(
        f"invalid trace {path}: {'; '.join(problems)}",
        context={"source": str(path), "errors": issues},
    )
